def numOfWays(points):
    # Map point for O(1) check
    point_set = set((x, y) for x, y in points)
    n = len(points)
    result = 0

    # Try every possible Alice and Bob pair
    for i in range(n):
        x1, y1 = points[i]
        for j in range(n):
            if i == j:
                continue
            x2, y2 = points[j]
            # Alice needs to be upper-left of Bob
            if x1 < x2 and y1 < y2:
                # Check all other points if any are inside/on boundary
                intruder = False
                for k in range(n):
                    if k == i or k == j:
                        continue
                    x, y = points[k]
                    # Boundary (including) but not Alice or Bob
                    if x1 <= x <= x2 and y1 <= y <= y2:
                        intruder = True
                        break
                if not intruder:
                    result += 1
    return result
